p='core/session.ts'; s=open(p).read()
s=s.replace("import { Injectable, inject, signal } from '@angular/core';","import { Injectable, computed, inject, signal } from '@angular/core';")
s=s.replace("""  readonly loading = signal(false);
""","""  readonly loading = signal(false);
  /** How many re-reads of the sheet's data, started by a (re-)load, have not answered yet. */
  private readonly reading = signal(0);
  /** True once the sheet is loaded and every re-read its load started has answered. */
  readonly ready = computed(() => !this.loading() && this.reading() === 0);
""")
s=s.replace("""  /** Change the active sheet's "today". */""","""  /** Count a re-read of the sheet's data, started by a (re-)load, until it answers. */
  async track(reread: Promise<unknown>): Promise<void> {
    this.reading.update((n) => n + 1);
    try {
      await reread;
    } finally {
      this.reading.update((n) => n - 1);
    }
  }

  /** Change the active sheet's "today". */""")
open(p,'w').write(s)

